SELECT COALESCE(test_coverage, 0) as "Test Coverage"
FROM v_repo_code_quality_latest
WHERE repo_id = '${repository}';

SELECT COALESCE(vulnerabilities, 0) as "Vulnerabilities"
FROM v_repo_dependency_rollup_latest
WHERE repo_id = '${repository}';

SELECT COALESCE(stale_branches, 0) as "Stale Branches"
